//파일다운로드
/**
 * @method
 * @name downloadFile
 * @description desc
 * @param {string} _appl_dd desc
 * @param {string} _appl_tm desc
 * @param {string} _file_type desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.downloadFile = function(_appl_dd, _appl_tm, _file_type) {
    var obj = document.downloadForm;
    obj.action = '/upload/downloadFile.do';
    obj.method.setValue('downloadFile');
    obj.appl_dd.setValue(_appl_dd);
    obj.appl_tm.setValue(_appl_tm);
    obj.file_type.setValue(_file_type);
    obj.submit();
};


