/**
 * @method
 * @name addMonth
 * @description desc
 * @param {string} y desc
 * @param {string} m desc
 * @param {string} d desc
 * @param {string} n desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.addMonth = function(y, m, d, n) {
    var dt = new Date(y, m - 1, d);
    //alert(dt);
    dt.setMonth(dt.getMonth() + n);
    //alert(dt);
    var lastdate = 32 - (new Date(dt.getYear(), dt.getMonth() - 1, 32).getDate());
    //alert(lastdate);
    var thisdate = dt.getDate();
    //alert(dt);

    dt.setDate((thisdate > lastdate) ? lastdate : thisdate);
    //alert(dt);
    return dt;
};
/**
 * @method
 * @name addMonth2
 * @description desc
 * @param {string} y desc
 * @param {string} m desc
 * @param {string} d desc
 * @param {string} n desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.addMonth2 = function(y, m, d, n) {
    var dt = new Date(y, m, d);
    dt.setMonth(dt.getMonth() - 1 + n);
    var lastdate = 32 - (new Date(dt.getYear(), dt.getMonth(), 32).getDate());
    var thisdate = dt.getDate();
    dt.setDate((thisdate > lastdate) ? lastdate : thisdate);
    return dt;
};
/**
 * @method
 * @name dateToyyyyMMdd
 * @description desc
 * @param {string} date desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.dateToyyyyMMdd = function(date) {
    var d = date.getDate();
    var m = date.getMonth() + 1;
    var y = date.getFullYear();
    return '' + y + '-' + (m <= 9 ? '0' + m : m) + '-' + (d <= 9 ? '0' + d : d);
};
/**
 * @method
 * @name Chk_Date
 * @description desc
 * @param {string} Name desc
 * @param {string} Date_Str desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.Chk_Date = function(Name, Date_Str) {
    var sdate = Name.getValue();
    var src;
    if (!scwin.Chk_Digit(Name.getValue())) {
        alert("입력한 " + Date_Str + "은(는)  숫자만 입력가능합니다.\n\r");
        Name.focus();
        Name.setValue('');
        return false;
    }
    pyear = sdate.substr(0, 4);
    pmonth = sdate.substr(4, 2);
    pday = sdate.substr(6, 2);
    src = pyear + '-' + pmonth + '-' + pday;
    syear = parseInt(pyear, 10);
    smonth = parseInt(pmonth, 10) - 1;
    sday = parseInt(pday, 10);
    sodate = new Date(Date.UTC(syear, smonth, sday));
    soyear = (sodate.getYear() < 2000) ? sodate.getYear() + 1900 : sodate.getYear();
    somonth = sodate.getMonth();
    soday = sodate.getDate();
    if (sdate != "" && (syear != soyear || smonth != somonth || sday != soday)) {
        alert("입력한 " + Date_Str + "이(가) 올바르지 않습니다 \n\r");
        Name.focus();
        Name.setValue('');
        return false;
    }
    if (sdate != "" && sdate.length != 8) {
        alert("입력한 " + Date_Str + "이(가) 8자리가 아닙니다. \n\r");
        Name.focus();
        Name.setValue('');
        return false;
    }

    /*
    if (sdate == "") {
        alert(Date_Str + "을 입력하십시오");
        Name.focus();
        return false;
    }
    */
    if (sdate == "") Name.setValue('');

    else Name.setValue(src);
    return true;
};
/**
 * @method
 * @name Chk_Date2
 * @description desc
 * @param {string} Name desc
 * @param {string} Date_Str desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.Chk_Date2 = function(Name, Date_Str) {
    var sdate = Name.getValue();
    var src;
    pyear = sdate.substr(0, 4);
    pmonth = sdate.substr(5, 2);
    pday = sdate.substr(8, 2);

    //src = pyear + '-' + pmonth + '-' + pday;

    syear = parseInt(pyear, 10);
    smonth = parseInt(pmonth, 10) - 1;
    sday = parseInt(pday, 10);
    sodate = new Date(Date.UTC(syear, smonth, sday));
    soyear = (sodate.getYear() < 2000) ? sodate.getYear() + 1900 : sodate.getYear();
    somonth = sodate.getMonth();
    soday = sodate.getDate();
    if (sdate != "" && (syear != soyear || smonth != somonth || sday != soday)) {
        alert("입력한 " + Date_Str + "이(가) 올바르지 않습니다 \n\r");
        Name.focus();
        Name.setValue('');
        return false;
    }
    if (sdate != "" && sdate.length != 10) {
        alert("입력한 " + Date_Str + "이(가) 8자리가 아닙니다. \n\r");
        Name.focus();
        Name.setValue('');
        return false;
    }
    return true;
};


// 숫자가 포함되어있는지 Check
/**
 * @method
 * @name Chk_Digit
 * @description desc
 * @param {string} str desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.Chk_Digit = function(str) {
    for (var i = 0; i < str.length; i++) {
        var ch = str.charAt(i);
        if ((ch < "0" || ch > "9") && ch != "-") {
            return false;
        }
    }
    return true;
};


// 숫자와 "." 포함되어있는지 Check
/**
 * @method
 * @name Chk_Digit_Point
 * @description desc
 * @param {string} str desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.Chk_Digit_Point = function(str) {
    var commCnt = 0;
    for (var i = 0; i < str.length; i++) {
        var ch = str.charAt(i);
        if ((ch < "0" || ch > "9") && ch != ".") {
            return false;
        }
        if (ch == ".") {
            commCnt++;
            if (commCnt > 1) {
                return false;
            }
        }
    }
    return true;
};


// 소수점체크 Check
