// 금액 입력시 "," 자동 입력 & 우측 정렬
/**
 * @method
 * @name Add_MoneyComma
 * @description desc
 * @param {string} Name desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.Add_MoneyComma = function(Name) {
    var src;
    var i;
    var factor;
    var su;
    var SpaceSize = 0;
    var size = 3;
    if (!scwin.Chk_Digit(Name.getValue())) {
        alert(" 숫자만 입력 가능합니다.");
        Name.setValue(""); //반복 예방2025.11.12
        Name.focus();
        Name.select();
        return false;
    }
    factor = Name.getValue().length % size;
    su = (Name.getValue().length - factor) / size;
    src = Name.getValue().substring(0, factor);
    for (i = 0; i < su; i++) {
        if ((factor == 0) && (i == 0)) {
            // "XXX" 인경우
            src += Name.getValue().substring(factor + (size * i), factor + size + (size * i));
        } else {
            src += ",";
            src += Name.getValue().substring(factor + (size * i), factor + size + (size * i));
        }
    }
    if (src.substring(0, 2) == '-,') {
        Name.setValue(src.substring(0, 1) + src.substring(2));
    } else {
        Name.setValue(src);
    }
    return true;
};


//금액 입력시 "," 자동 입력 & 우측 정렬
/**
 * @method
 * @name Add_MoneyComma_Value
 * @description desc
 * @param {string} v desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.Add_MoneyComma_Value = function(v) {
    var src;
    var i;
    var factor;
    var su;
    var SpaceSize = 0;
    var size = 3;
    factor = v.length % size;
    su = (v.length - factor) / size;
    src = v.substring(0, factor);
    for (i = 0; i < su; i++) {
        if ((factor == 0) && (i == 0)) {
            // "XXX" 인경우
            src += v.substring(factor + (size * i), factor + size + (size * i));
        } else {
            src += ",";
            src += v.substring(factor + (size * i), factor + size + (size * i));
        }
    }
    if (src.substring(0, 2) == '-,') {
        v = src.substring(0, 1) + src.substring(2);
    } else {
        v = src;
    }
    return v;
};


// 컴마(",") 자동 삭제
/**
 * @method
 * @name Del_MoneyComma
 * @description desc
 * @param {string} Name desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.Del_MoneyComma = function(Name) {
    var x, ch;
    var i = 0;
    var newVal = "";
    for (x = 0; x < Name.getValue().length; x++) {
        ch = Name.getValue().substring(x, x + 1);
        if (ch != ",") newVal += ch;
    }
    Name.setValue(newVal);
    return true;
};


// 컴마(",") 자동 삭제
/**
 * @method
 * @name Del_MoneyComma_Value
 * @description desc
 * @param {string} v desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.Del_MoneyComma_Value = function(v) {
    var value = v;
    var x, ch;
    var i = 0;
    var newVal = "";
    for (x = 0; x < value.length; x++) {
        ch = value.substring(x, x + 1);
        if (ch != ",") newVal += ch;
    }
    value.setValue(newVal);
    return value;
};


