/**
 * @method
 * @name CheckEmail
 * @description desc
 * @param {string} email_addr desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.CheckEmail = function(email_addr) {
    if (email_addr == "") return false;
    var t = email_addr;
    var Alpha = 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ';
    var Digit = '1234567890';
    var Symbol = '_ -';
    var check = '@.' + Alpha + Digit + Symbol;
    for (i = 0; i < t.length; i++)
        if (check.indexOf(t.substring(i, i + 1)) < 0) {
            return false;
        } var check = '@';
    var a = 0;
    for (i = 0; i < t.length; i++)
        if (check.indexOf(t.substring(i, i + 1)) >= 0) a = i;
    var check = '.';
    var b = 0;
    for (i = a + 1; i < t.length; i++)
        if (check.indexOf(t.substring(i, i + 1)) >= 0) b = i;
    if (a != 0 && b != 0 && b != t.length - 1) {
        return true;
    } else {
        return false;
    }
};
/**
 * @method
 * @name ietruebody
 * @description desc
 * @param
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.ietruebody = function() {
    if (document.documentElement && document.documentElement.scrollTop) // ie6 Strict 
        return document.documentElement;

    else if (document.documentElement && document.documentElement.clientHeight) // ie6 Strict 
        return document.documentElement;

    else if (document.body) // ie < ie 6 
        return document.body;
};
/**
 * @method
 * @name quick_init
 * @description desc
 * @param
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.quick_init = function() {
    var apt = 100;
    var bst = $('body').prop("scrollTop");
    if ($.browser.msie) {
        bst = scwin.ietruebody().scrollTop;
    }
    if (bst >= apt) {
        $("div.quickmenu").addClass("top");
    } else {
        $("div.quickmenu").removeClass("top");
    }
};
/**
 * @method
 * @name fn_CheckDate
 * @description desc
 * @param {string} obj desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_CheckDate = function(obj) {
    if (obj.getValue().length == 0) return true;
    obj.setValue(removeChar(obj.getValue(), '-'));
    obj.setValue(removeChar(obj.getValue(), '/'));
    if (obj.getValue().length != 8) {
        alert(obj.alt + ': ' + '날짜는 8 자리 YYYYMMDD 형식입니다.');
        obj.focus();
        obj.select();
        return false;
    }
    if (obj.getValue() != '' && !isMinusNum(obj.getValue())) {
        alert(obj.alt + ': ' + "숫자만 입력가능합니다.");
        obj.focus();
        obj.select();
        return false;
    }
    var year = obj.getValue().substring(0, 4);
    var month = obj.getValue().substring(4, 6);
    var day = obj.getValue().substring(6, 8);
    if (month > 12 || month < 1) {
        alert(obj.alt + ': ' + '달은 1 에서 12 사이여야 합니다.');
        obj.focus();
        obj.select();
        return false;
    }
    if (day > 31 || day < 1) {
        alert(obj.alt + ': ' + '날은 1 에서 31 사이여야 합니다.');
        obj.focus();
        obj.select();
        return false;
    }
    return true;
};



