/* 숫자를 제외한 입력은 입력되지 않게 한다 */
/**
 * @method
 * @name NumberCheck
 * @description desc
 * @param {string} obj desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.NumberCheck = function(obj) {
    var keyVal = window.event.keyCode;
    //alert(keyVal);
    if (keyVal == 13 || keyVal == 0) {
        return;
    }
    if ((keyVal > 47 && keyVal < 58) || keyVal == 8 || keyVal == 9 || keyVal == 16 || keyVal == 60 || keyVal == 144) {
        if ((keyVal > 47 && keyVal < 58) || (keyVal > 95 && keyVal < 106) || keyVal == 60) {
            if (window.event.shiftKey) event.preventDefault ? event.preventDefault() : event.returnValue = false;

            else event.returnValue = true;
        }
    } else {
        alert("숫자로만 입력하세요.");
        obj.setValue("");
        obj.focus();
        event.preventDefault ? event.preventDefault() : event.returnValue = false;
    }
};



