/*
 * byte수 초과시 자르기
 */
/**
 * @method
 * @name byteCheck
 * @description desc
 * @param {string} obj desc
 * @param {string} bt desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.byteCheck = function(obj, bt) {
    var text = obj.getValue();
    var msglen = 0;
    msglen = scwin.reCount(text);
    if (msglen > bt) {
        rem = msglen - bt;
        //alert('입력하신 문장의 총길이는 ' + msglen + '입니다.\n초과되는 ' + rem + '바이트는 삭제됩니다.');
        alert("입력하신 항목은 한글 " + (bt / 2) + "자, 영문 " + bt + "자까지 가능합니다.\n초과되는 " + rem + "바이트는 삭제됩니다.");
        obj.setValue(scwin.cutMsg(text, bt));
    } else {

        //return msg;

        //obj.value = msg

    }

};
/**
 * @method
 * @name cutMsg
 * @description desc
 * @param {string} str desc
 * @param {string} bt desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.cutMsg = function(str, bt) {
    var ret = '';
    var i;
    var msglen = 0;
    for (i = 0; i < str.length; i++) {
        var ch = str.charAt(i);
        if (escape(ch).length > 4) {
            msglen += 2;
        } else {
            msglen++;
        }
        if (msglen > bt) break;
        ret += ch;
    }
    return ret;
};
/**
 * @method
 * @name reCount
 * @description desc
 * @param {string} str desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.reCount = function(str) {
    var i;
    var msglen = 0;
    for (i = 0; i < str.length; i++) {
        var ch = str.charAt(i);
        if (escape(ch).length > 4) {
            msglen += 2;
        } else {
            msglen++;
        }
    }
    return msglen;
};
/**
 * @method
 * @name replacePercent
 * @description desc
 * @param {string} obj desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.replacePercent = function(obj) {
    if (window.event.keyCode == 37) {
        alert("검색어에 다음 문자를 사용할 수 없습니다.\n\n%");
        event.returnValue = false;
    }
    if (obj.getValue().indexOf('%') != -1) {
        alert("검색어에 다음 문자를 사용할 수 없습니다.\n\n%");
        obj.setValue(obj.getValue().replace(/%/gi, ""));
        return false;
    }
};



//Time스트링을 자바스크립트 Date객체로 변환
/**
 * @method
 * @name toTimeObject
 * @description desc
 * @param {string} time desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.toTimeObject = function(time) {
    var year = time.substr(0, 4);
    var month = time.substr(4, 2) - 1;
    var day = time.substr(6, 2);
    var hour = '00';
    var min = '00';
    return new Date(year, month, day, hour, min);
};


//Time이 현재시각이전인지 체크
/**
 * @method
 * @name isPastTime
 * @description desc
 * @param {string} time desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.isPastTime = function(time) {
    return (scwin.toTimeObject(time) < new Date());
};


//Time이 현재월 마지막날 이후인지 체크
/**
 * @method
 * @name isNextMonth
 * @description desc
 * @param {string} time desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.isNextMonth = function(time) {
    var now = new Date();
    var y = now.getFullYear();
    var m = now.getMonth() + 1;
    var newDay = new Date(y, m, "");
    var lastDay = newDay.getDate();
    return (scwin.toTimeObject(time) <= new Date(y, m - 1, lastDay));
};


