// 문자열채우기
// str 원본문자열
// n 문자열총길이 (n<0:우측, n>0:좌측)
// chr 채울문자열
/**
 * @method
 * @name fill
 * @description desc
 * @param {string} str desc
 * @param {string} n desc
 * @param {string} chr desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fill = function(str, n, chr) {
    str += "";
    if (chr == undefined) {
        chr = " ";
    }
    var i;
    var c = "";
    if (n < 0) {
        for (i = str.length; i < -n; i++) {
            c += chr;
        }
        return str + c;
    } else {
        for (i = str.length; i < n; i++) {
            c += chr;
        }
        return c + str;
    }
};




