//lpad
/**
 * @method
 * @name fnLPAD
 * @description desc
 * @param {string} val desc
 * @param {string} set desc
 * @param {string} cnt desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fnLPAD = function(val, set, cnt) {
    if (!set || !cnt || val.length >= cnt) {
        return val;
    }
    var max = (cnt - val.length) / set.length;
    for (var i = 0; i < max; i++) {
        val = set + val;
    }
    return val;
};



