/*
 * 항목 활성/비활성
 * sCompId : 항목ID
 * bEnable : true 활성
 *           false 비활성
 * bInitVal : 값 초기화 여부
 *
 */
/**
 * @method
 * @name fn_CompEnable
 * @description desc
 * @param {string} sCompId desc
 * @param {string} bEnable desc
 * @param {string} bInitVal desc
 * @param {string} bStyle desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_CompEnable = function(sCompId, bEnable, bInitVal, bStyle) {
    if (bInitVal == undefined) {
        bInitVal = true;
    }
    if (bStyle == undefined) {
        bStyle = false;
    }
    if (bEnable) {
        $("#" + sCompId).removeAttr("disabled");
        $("#" + sCompId).attr("style", "background:");
    } else {
        $("#" + sCompId).attr("disabled", true);
        if (bInitVal) {
            $("#" + sCompId).val("");
        }
        if (bStyle) {
            $("#" + sCompId).attr("style", "background:#e2e2e2;");
        }
    }
};




//수신동의 체크
/**
 * @method
 * @name fn_click_all_rcv_yn
 * @description desc
 * @param {string} obj desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_click_all_rcv_yn = function(obj) {
    if (obj.checked) {
        $("#email_rcv_yn").attr("checked", true);
        $("#sms_rcv_yn").attr("checked", true);
    } else {
        $("#email_rcv_yn").attr("checked", false);
        $("#sms_rcv_yn").attr("checked", false);
    }
};



//브라우저체크
/**
 * @method
 * @name checkBroswer
 * @description desc
 * @param
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.checkBroswer = function() {
    var agent = navigator.userAgent.toLowerCase(),
        name = navigator.appName,
        browser = '';
    showAlertFlag = false;

    // MS 계열 브라우저를 구분
    if (name === 'Microsoft Internet Explorer' || agent.indexOf('trident') > -1 || agent.indexOf('edge/') > -1) {
        browser = 'ie';
        if (name === 'Microsoft Internet Explorer') {
            // IE old version (IE 10 or Lower)
            agent = /msie ([0-9]{1,}[\.0-9]{0,})/.exec(agent);
            browser += parseInt(agent[1]);
        } else {
            // IE 11+
            if (agent.indexOf('trident') > -1) {
                // IE 11
                browser += 11;
            } else if (agent.indexOf('edge/') > -1) {
                // Edge
                browser = 'Edge';
                showAlertFlag = true;
            }
        }
    } else if (agent.indexOf('safari') > -1) {
        // Chrome or Safari
        if (agent.indexOf('opr') > -1) {
            // Opera
            browser = 'Opera';
        } else if (agent.indexOf('chrome') > -1) {
            // Chrome
            browser = 'Chrome';
        } else {
            // Safari
            browser = 'Safari';
        }
        showAlertFlag = true;
    } else if (agent.indexOf('firefox') > -1) {
        // Firefox
        browser = 'Firefox';
        showAlertFlag = true;
    } else {
        browser = '해당';
        showAlertFlag = true;
    }

    //익스플로러를 제외한 브라우저에서 안내메세지 표출
    if (showAlertFlag) {
        alert("채권상장시스템은 " + browser + " 계열 브라우저에서 일부 기능이 제한됩니다.\n\n시스템의 안정적 사용을 위하여 'Internet Explorer 11'을 사용하시기 바랍니다.");
    }
    //alert(browser);

};




/*=============================================================================*
 * 입력값이 숫자인지를 확인하고 포멧을 만들어준다
 * param : sdateVal 입력스트링
 * return : Boolean True이면 숫자값
 *============================================================================*/
/**
 * @method
 * @name chkDate2
 * @description desc
 * @param {string} calObj desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.chkDate2 = function(calObj) {
    var dateVal = calObj.getValue();
    if (dateVal.length < 1) {
        return;
    }
    var dateVal2 = rtnNumber(dateVal);
    window.status = dateVal2.length;
    if (dateVal2.length < 1) {
        calObj.setValue("");
    } else if (dateVal2.length >= 1 && dateVal2.length < 8) {
        calObj.setValue(dateVal2);
    } else if (dateVal2.length == 8) {
        calObj.setValue(dateVal2.substring(0, 4) + "-" + dateVal2.substring(4, 6) + "-" + dateVal2.substring(6, 8));
    } else if (dateVal2.length > 8) {
        calObj.setValue(dateVal2.substring(0, 4) + "-" + dateVal2.substring(4, 6) + "-" + dateVal2.substring(6, 8));
    }
};
